int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port, struct br_ip *group) {
    int result = 0;

    // Acquire the multicast lock of the bridge
    rwlock_acquire_read(&br->multicast_lock);

    // Check if the bridge is running and if the port is enabled
    if (!br->running) {
        result = -ENODEV;
        goto unlock;
    }

    if (port && !port->enabled) {
        result = -ENODEV;
        goto unlock;
    }

    // Create a new multicast group entry
    if (!port) {
        struct br_multicast *mcast;
        mcast = kzalloc(sizeof(*mcast), GFP_KERNEL);
        if (!mcast) {
            result = -ENOMEM;
            goto unlock;
        }

        mcast->group = *group;
        list_add(&mcast->list, &br->multicast_list);
    } else {
        struct br_port_group *pg;
        pg = kzalloc(sizeof(*pg), GFP_KERNEL);
        if (!pg) {
            result = -ENOMEM;
            goto unlock;
        }

        pg->group = *group;
        timer_setup(&pg->timer, br_mcast_timer, 0);
        pg->timer.expires = jiffies + br->multicast_membership_interval;
        add_timer(&pg->timer);

        list_add(&pg->list, &port->multicast_list);
    }

unlock:
    // Release the lock
    rwlock_release_read(&br->multicast_lock);
    return result;
}

int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port,
                           struct br_ip *group) {
    int err = 0;

    spin_lock(&br->multicast_lock);
    if (!netif_running(br->dev)) {
        err = -EINVAL;
        goto out;
    }

    if (!port) {
        list_add(&group->mg_list, &br->multicast_list);
    } else {
        struct net_bridge_port_group *pgrp = kmalloc(sizeof(*pgrp), GFP_ATOMIC);
        if (!pgrp) {
            err = -ENOMEM;
            goto out;
        }

        pgrp->group = *group;
        INIT_LIST_HEAD(&pgrp->mg_list);
        list_add(&pgrp->mg_list, &port->multicast_list);
        pgrp->timer_expires = jiffies + br->multicast_membership_interval;
        pgrp->query_timer_expires = jiffies + br->multicast_query_interval;
    }

out:
    spin_unlock(&br->multicast_lock);
    return err;
}

int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port, struct br_ip *group) {
    int err = 0;

    spin_lock(&br->multicast_lock);

    if (!netif_running(br->dev)) {
        spin_unlock(&br->multicast_lock);
        return -EINVAL;
    }

    if (port && !port->enabled) {
        spin_unlock(&br->multicast_lock);
        return -EINVAL;
    }

    struct br_mcast *mcast;
    mcast = kzalloc(sizeof(*mcast), GFP_ATOMIC);
    if (!mcast) {
        spin_unlock(&br->multicast_lock);
        return -ENOMEM;
    }

    memcpy(&mcast->group, group, sizeof(*group));

    if (!port) {
        hlist_add_head(&mcast->hlist, &br->multicast_list);
    } else {
        struct br_mcast_port *port_mcast;

        port_mcast = kzalloc(sizeof(*port_mcast), GFP_ATOMIC);
        if (!port_mcast) {
            kfree(mcast);
            spin_unlock(&br->multicast_lock);
            return -ENOMEM;
        }

        port_mcast->mcast = mcast;
        timer_setup(&port_mcast->membership_timer, NULL, 0);
        timer_setup(&port_mcast->query_timer, NULL, 0);

        hlist_add_head(&port_mcast->hlist, &port->multicast_list);
    }

    spin_unlock(&br->multicast_lock);
    return err;
}

int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port, struct br_ip *group) {
    int err = 0;

    spin_lock(&br->multicast_lock);

    if (!netif_running(br->dev)) {
        err = -EINVAL;
        goto out;
    }

    if (port && !port->enabled) {
        err = -EINVAL;
        goto out;
    }

    struct br_mdb_entry *new_entry = kzalloc(sizeof(*new_entry), GFP_ATOMIC);
    if (!new_entry) {
        err = -ENOMEM;
        goto out;
    }

    if (!port) {
        hlist_add_head(&new_entry->hlist, &br->mdb);
    } else {
        struct br_mdb_port_group *new_port_group = kzalloc(sizeof(*new_port_group), GFP_ATOMIC);
        if (!new_port_group) {
            kfree(new_entry);
            err = -ENOMEM;
            goto out;
        }

        new_port_group->group = *group;
        new_port_group->port = port;
        new_port_group->timer.function = br_ip4_multicast_timer_expired;
        new_port_group->timer.data = (unsigned long)new_port_group;

        hlist_add_head(&new_port_group->hlist, &port->mcast_list);
        mod_timer(&new_port_group->timer, jiffies + BR_MCAST_TIMER_INTERVAL);
    }

out:
    spin_unlock(&br->multicast_lock);
    return err;
}

int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port, struct br_ip *group) {
    int ret = 0;

    spin_lock(&br->multicast_lock);

    if (!(br->flags & BRIDGE_FLAGS_RUNNING) || (port && !(port->flags & BRIDGE_PORT_FLAGS_ENABLED))) {
        ret = -EINVAL;
        goto unlock;
    }

    struct br_multicast_entry *entry = kmalloc(sizeof(*entry), GFP_KERNEL);
    if (!entry) {
        ret = -ENOMEM;
        goto unlock;
    }

    entry->group = *group;

    if (!port) {
        list_add(&entry->list, &br->multicast_list);
    } else {
        struct br_multicast_port_group *pg;

        pg = kmalloc(sizeof(*pg), GFP_KERNEL);
        if (!pg) {
            ret = -ENOMEM;
            kfree(entry);
            goto unlock;
        }

        pg->port = port;
        pg->group = *group;
        INIT_LIST_HEAD(&pg->timer_list);

        br_multicast_set_timers(pg);

        list_add(&pg->list, &port->multicast_list);
        entry->port_group = pg;
    }

unlock:
    spin_unlock(&br->multicast_lock);
    return ret;
}
